  1→// Собирает свежие данные через collect.js и превращает их в data.js,
  2→// который варианты интерфейса подключают обычным <script src>.
  3→// Так работает открытие двойным кликом: fetch локального JSON с file:// браузер блокирует,
  4→// а classic-скрипт — нет.
  5→//
  6→// Использование:
  7→//   bun refresh.js            — 24 часа, Screenpipe должен быть запущен
  8→//   bun refresh.js 480 8      — окно 480 минут, дискретизация кадров 8 секунд
  9→//   bun refresh.js --sample   — пересобрать data.js из data-sample.js (демо-данные)
 10→import { readFile, copyFile } from "node:fs/promises";
 11→import { existsSync } from "node:fs";
 12→import { join } from "node:path";
 13→
 14→const DIR = import.meta.dir;
 15→const COLLECT = join(DIR, "..", "collect.js");
 16→const RAW = join(DIR, "..", "data.json");
 17→const OUT = join(DIR, "data.js");
 18→
 19→const wrap = (json, meta) =>
 20→  `// Сгенерировано refresh.js ${new Date().toISOString()}\n` +
 21→  `window.__ACTIVITY__ = ${json};\n` +
 22→  `window.__ACTIVITY_META__ = ${JSON.stringify(meta, null, 2)};\n`;
 23→
 24→async function fromSample() {
 25→  const src = join(DIR, "data-sample.js");
 26→  if (!existsSync(src)) throw new Error("Нет data-sample.js — сначала bun make-sample.js");
 27→  const code = await readFile(src, "utf8");
 28→  await Bun.write(OUT, "// ДЕМО-режим: data.js собран из data-sample.js\n" + code.replace(/^\/\/[^\n]*\n/gm, ""));
 29→  console.log(JSON.stringify({ out: OUT, mode: "sample", note: "В интерфейсе будет бейдж ДЕМО" }));
 30→}
 31→
 32→async function fromScreenpipe(minutes, stride) {
 33→  if (!existsSync(COLLECT)) throw new Error(`Не найден collect.js: ${COLLECT}`);
 34→  const proc = Bun.spawn(["bun", COLLECT, String(minutes), RAW], {
 35→    cwd: join(DIR, ".."),
 36→    stdout: "pipe",
 37→    stderr: "pipe",
 38→  });
 39→  const [out, err, code] = await Promise.all([
 40→    new Response(proc.stdout).text(),
 41→    new Response(proc.stderr).text(),
 42→    proc.exited,
 43→  ]);
 44→  if (code !== 0) {
 45→    console.error(err.trim() || out.trim());
 46→    throw new Error("collect.js упал. Проверь, что Screenpipe запущен: http://localhost:3030/health");
 47→  }
 48→  console.log(out.trim());
 49→
 50→  if (existsSync(RAW + ".bak")) await copyFile(RAW + ".bak", RAW + ".prev");
 51→  await copyFile(RAW, RAW + ".bak");
 52→
 53→  const raw = await readFile(RAW, "utf8");
 54→  let payload;
 55→  try {
 56→    payload = JSON.parse(raw);
 57→  } catch {
 58→    throw new Error("collect.js записал невалидный JSON");
 59→  }
 60→  const empty = ["frames", "switches", "clicks"].filter((k) => !payload[k]?.length);
 61→  await Bun.write(
 62→    OUT,
 63→    wrap(JSON.stringify(payload), {
 64→      source: "data.json",
 65→      sample: false,
 66→      generated_at: payload.generated_at,
 67→      window_minutes: payload.window_minutes,
 68→      sources: {
 69→        frames: payload.frames?.length ?? 0,
 70→        switches: payload.switches?.length ?? 0,
 71→        clicks: payload.clicks?.length ?? 0,
 72→        url_hits: payload.url_hits?.length ?? 0,
 73→      },
 74→      empty_sources: empty,
 75→    }),
 76→  );
 77→  console.log(JSON.stringify({
 78→    out: OUT,
 79→    mode: "live",
 80→    window_minutes: payload.window_minutes,
 81→    frames: payload.frames?.length ?? 0,
 82→    switches: payload.switches?.length ?? 0,
 83→    clicks: payload.clicks?.length ?? 0,
 84→    url_hits: payload.url_hits?.length ?? 0,
 85→    empty_sources: empty,
 86→  }));
 87→  if (empty.length) {
 88→    console.log(
 89→      "\n[!] Пустые источники: " + empty.join(", ") +
 90→      "\n    Обычно это значит, что записи в них нет за выбранное окно." +
 91→      "\n    Увеличь окно: bun refresh.js 10080",
 92→    );
 93→  }
 94→}
 95→
 96→const args = process.argv.slice(2);
 97→try {
 98→  if (args[0] === "--sample") {
 99→    await fromSample();
100→  } else {
101→    await fromScreenpipe(parseInt(args[0] || "1440", 10), parseInt(args[1] || "0", 10));
102→  }
103→} catch (e) {
104→  console.error("FAILED:", e.message);
105→  process.exit(1);
106→}

  1→// Генерирует правдоподобный демо-снимок активности за 24 часа.
  2→// Нужен, чтобы варианты интерфейса было что показать, когда Screenpipe не запущен.
