  7→// Детерминированный ГПСЧ — чтобы повторный запуск давал тот же результат.
  8→let seed = 20261013;
  9→const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);
 10→const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
 11→const between = (a, b) => a + Math.floor(rnd() * (b - a + 1));
 12→
 13→const day0 = new Date(`${DAY}T00:00:00+03:00`);
 14→// Локальный ISO с наносекундами — ровно такой формат отдаёт Screenpipe.
 15→const iso = (ms) => {
 16→  const d = new Date(ms);
 17→  const off = 3 * 60;
 18→  const local = new Date(d.getTime() + off * 60000);
 19→  const p = (n, w = 2) => String(n).padStart(w, "0");
 20→  return (
 21→    `${local.getUTCFullYear()}-${p(local.getUTCMonth() + 1)}-${p(local.getUTCDate())}` +
 22→    `T${p(local.getUTCHours())}:${p(local.getUTCMinutes())}:${p(local.getUTCSeconds())}` +
 23→    `.${String(local.getUTCMilliseconds()).padStart(3, "0")}000+03:00`
 24→  );
 25→};
 26→const at = (h, m) => day0.getTime() + (h * 60 + m) * 60000;
