 98→let prevApp = "";
 99→for (const [app, win, h, m, dur, density] of BLOCKS) {
100→  const start = at(h, m);
101→  const end = start + dur * 60000;
102→
103→  if (prevApp && prevApp !== app) {
104→    switches.push({ timestamp: iso(start - between(2, 25) * 1000), app_name: app, window_title: win });
105→    eventTally.app_switch++;
106→  }
107→  prevApp = app;
108→
109→  // Кадры: интервал 20–50 секунд, окно сосредоточено.
110→  for (let ts = start; ts <= end; ts += between(20000, 50000)) {
111→    const focused = rnd() > 0.06;
112→    frames.push({
113→      timestamp: iso(ts),
114→      app_name: app,
115→      window_name: win,
116→      browser_url: app === "chrome.exe" && rnd() > 0.5 ? CHROME_HOSTS[win]?.[0]?.[1] ?? "" : "",
117→      focused,
118→    });
119→    if (focused) eventTally.focus_change++;
120→  }
121→
122→  // Клики: 0.4–5 в минуту в зависимости от плотности.
123→  for (let ts = start; ts <= end; ts += 60000) {
124→    const n = Math.round(density * between(1, 6));
125→    for (let i = 0; i < n; i++) {
126→      clicks.push({ timestamp: iso(ts + between(0, 59000)), app_name: app });
127→      eventTally.click++;
128→    }
129→    eventTally.key_press += Math.round(density * between(20, 140));
130→    eventTally.scroll += Math.round(density * between(5, 40));
131→  }
