133→  // Домены: только из Chrome-блоков, ~1–2 в минуту.
134→  const hosts = CHROME_HOSTS[win];
135→  if (hosts) {
136→    for (let ts = start; ts <= end; ts += between(30000, 75000)) {
137→      const [host, url] = pick(hosts);
138→      url_hits.push({ host, url, ts: iso(ts), app, window: win });
139→    }
140→  }
